CREATE TABLE `noobdb_ct_mysql_opts` (
  `id` INT NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `noobdb_ct_mysql_range_cols` (
  `id` INT NOT NULL,
  `created` DATE NOT NULL,
  PRIMARY KEY (`id`, `created`)
)
PARTITION BY RANGE COLUMNS (`created`) (
  PARTITION `p0` VALUES LESS THAN ('2026-01-01')
);

CREATE TABLE `noobdb_ct_mysql_range_multi` (
  `a` INT NOT NULL,
  `b` INT NOT NULL,
  PRIMARY KEY (`a`, `b`)
)
PARTITION BY RANGE COLUMNS (`a`, `b`) (
  PARTITION `p0` VALUES LESS THAN (10, 20)
);

CREATE TABLE `noobdb_ct_mysql_range_expr` (
  `id` INT NOT NULL,
  `created` DATE NOT NULL,
  PRIMARY KEY (`id`, `created`)
)
PARTITION BY RANGE (YEAR(created)) (
  PARTITION `pmax` VALUES LESS THAN MAXVALUE
);

CREATE TABLE `noobdb_ct_mysql_list` (
  `id` INT NOT NULL,
  PRIMARY KEY (`id`)
)
PARTITION BY LIST (`id`) (
  PARTITION `pa` VALUES IN (1, 2, 3)
);

CREATE TABLE `noobdb_ct_mysql_hash` (
  `id` INT NOT NULL,
  PRIMARY KEY (`id`)
)
PARTITION BY HASH (`id`) PARTITIONS 4;

CREATE TABLE `noobdb_ct_mysql_key` (
  `id` INT NOT NULL,
  PRIMARY KEY (`id`)
)
PARTITION BY KEY (`id`) PARTITIONS 4;

CREATE UNLOGGED TABLE "noobdb_ct_pg_unlogged" (
  "id" INTEGER NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "noobdb_ct_pg_range" (
  "id" INTEGER NOT NULL,
  PRIMARY KEY ("id")
) PARTITION BY RANGE ("id");

CREATE TABLE "noobdb_ct_pg_list" (
  "region" TEXT NOT NULL,
  PRIMARY KEY ("region")
) PARTITION BY LIST ("region");

CREATE TABLE "noobdb_ct_pg_hash" (
  "id" INTEGER NOT NULL,
  PRIMARY KEY ("id")
) PARTITION BY HASH ("id");

CREATE TABLE "noobdb_ct_pg_parent_only" (
  "id" INTEGER NOT NULL,
  PRIMARY KEY ("id")
) PARTITION BY RANGE ("id");

CREATE TABLE "noobdb_ct_sqlite_strict" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "label" TEXT
) STRICT;

CREATE TABLE "noobdb_ct_sqlite_wr" (
  "k" TEXT NOT NULL,
  "v" INTEGER,
  PRIMARY KEY ("k")
) WITHOUT ROWID;

CREATE TABLE "noobdb_ct_sqlite_both" (
  "k" TEXT NOT NULL,
  "v" INTEGER,
  PRIMARY KEY ("k")
) STRICT, WITHOUT ROWID;
